style.css:
@-moz-document domain("youtube.com") {
/* palet warna */
:root {
  --my-navy: #193b5b;
  --my-blue: #527b9d;
  --my-dusty: #a9c2d5;
  --my-ice: #dce8ef;
  --my-ivory: #f3eee5;
}

/* lukisan sebagai background */
html,
body,
ytd-app {
  background-color: #193b5b !important;
  background-image:
    linear-gradient(
      rgba(18, 48, 76, 0.28),
      rgba(18, 48, 76, 0.38)
    ),
    url("https://i.ibb.co/1J4HcQ7v/amazing-attention-to-detail.jpg") !important;
  background-size: cover !important;
  background-position: center !important;
  background-attachment: fixed !important;
  background-repeat: no-repeat !important;
}

/* header */
ytd-masthead {
  background: rgba(25, 59, 91, 0.78) !important;
  backdrop-filter: blur(16px) !important;
}

/* sidebar */
#guide-content,
ytd-mini-guide-renderer {
  background: rgba(22, 48, 73, 0.72) !important;
  backdrop-filter: blur(16px) !important;
}

/* konten transparan */
ytd-page-manager,
#primary,
#secondary {
  background: transparent !important;
}

/* warna tulisan */
ytd-app {
  --yt-spec-text-primary: #f3eee5 !important;
  --yt-spec-text-secondary: #dce8ef !important;
}

/* kolom pencarian */
#center input {
  background: rgba(220, 232, 239, 0.15) !important;
  border: 1px solid rgba(220, 232, 239, 0.5) !important;
  border-radius: 24px !important;
  color: #f3eee5 !important;
}

/* thumbnail */
ytd-thumbnail img {
  border-radius: 12px !important;
}

/* kategori */
yt-chip-cloud-chip-renderer {
  border-radius: 20px !important;
}
}
